import { mkdtemp, readFile, readdir, rm, stat } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { expect, test } from "vitest";
import { withImageUpload } from "./image-upload.ts";
import type { SocialImageData } from "@ren-ai/onboarding/social-images";

const image: SocialImageData = {
  id: "draft",
  mime: "image/jpeg",
  data: Buffer.from([255, 216, 255, 254, 0, 2, 255, 217]).toString("base64"),
};
test.each([false, true])(
  "upload files are private, contain the generated bytes, and are removed after success or failure (%s)",
  async (fail) => {
    const home = await mkdtemp(join(tmpdir(), "social-upload-"));
    try {
      const operation = withImageUpload(home, image, async (path) => {
        expect((await stat(path)).mode & 0o777).toBe(0o600);
        expect((await readFile(path)).toString("base64")).toBe(image.data);
        if (fail) throw new Error("upload failed");
        return "uploaded";
      });
      expect(await operation.catch((cause: Error) => cause.message)).toBe(
        fail ? "upload failed" : "uploaded",
      );
      expect(await readdir(join(home, "uploads"))).toEqual([]);
    } finally {
      await rm(home, { recursive: true, force: true });
    }
  },
);
test.each([
  "",
  "not-base64",
  Buffer.from([1, 2, 3, 4, 5]).toString("base64"),
  Buffer.from([255, 216, 1, 2, 3]).toString("base64"),
])("invalid image bytes never reach the uploader: %s", async (data) => {
  await expect(
    withImageUpload("/unused", { ...image, data }, async () => "not reached"),
  ).rejects.toThrow("Invalid social image JPEG");
});
